class SgfTree:
    def __init__(self, properties=None, children=None):
        self.properties = properties or {}
        self.children = children or []

    def __eq__(self, other):
        if not isinstance(other, SgfTree):
            return False
        pending = [(self, other)]

        # Nodes in a sequence form a long single-child chain.  Compare the
        # tree explicitly so large game records do not consume Python's
        # recursion limit.
        while pending:
            current, other_current = pending.pop()
            if current.properties != other_current.properties:
                return False
            if len(current.children) != len(other_current.children):
                return False

            for child, other_child in zip(current.children, other_current.children):
                if isinstance(child, SgfTree) and isinstance(other_child, SgfTree):
                    pending.append((child, other_child))
                elif child != other_child:
                    return False

        return True

    def __ne__(self, other):
        return not self == other

    def __repr__(self):
        # Build the representation iteratively as well, so displaying a
        # deeply nested tree remains safe.
        parts = []
        pending = [("tree", self)]
        active = set()

        while pending:
            kind, value = pending.pop()

            if kind == "text":
                parts.append(value)
                continue

            if kind == "exit":
                active.remove(value)
                continue

            tree_id = id(value)
            if tree_id in active:
                parts.append("<cycle>")
                continue

            active.add(tree_id)
            parts.append("SgfTree(properties=")
            parts.append(repr(value.properties))
            parts.append(", children=[")

            pending.append(("text", "]))"))
            pending.append(("exit", tree_id))
            for index in range(len(value.children) - 1, -1, -1):
                if index < len(value.children) - 1:
                    pending.append(("text", ", "))
                child = value.children[index]
                if isinstance(child, SgfTree):
                    pending.append(("tree", child))
                else:
                    pending.append(("text", repr(child)))

        return "".join(parts)


class _Parser:
    """Small recursive-descent parser for the part of SGF used here."""

    def __init__(self, input_string):
        self.input = input_string
        self.position = 0

    def parse(self):
        if not self.input or self.input[0] != "(":
            raise ValueError("tree missing")

        tree = self._parse_tree()
        if self.position != len(self.input):
            raise ValueError("unexpected input")
        return tree

    def _parse_tree(self):
        self._expect("(", "tree missing")

        # A game tree must contain a sequence, and a sequence must start
        # with a node.  An empty node itself is valid, so '(;)' is valid.
        if self._at_end() or self._current() != ";":
            raise ValueError("tree with no nodes")

        root = self._parse_node()
        # Each frame stores the root and final node of a game tree, plus
        # whether its sequence has transitioned to child variations.  An
        # explicit stack avoids recursion for deeply nested variations.
        frames = [[root, root, False]]

        while frames:
            frame = frames[-1]
            last = frame[1]

            if self._at_end():
                raise ValueError("tree missing")

            character = self._current()
            if character == ";":
                if frame[2]:
                    raise ValueError("tree missing")

                child = self._parse_node()
                last.children.append(child)
                frame[1] = child
            elif character == "(":
                frame[2] = True
                self.position += 1

                if self._at_end() or self._current() != ";":
                    raise ValueError("tree with no nodes")

                child = self._parse_node()
                frames.append([child, child, False])
            elif character == ")":
                self.position += 1
                completed = frame[0]
                frames.pop()

                if not frames:
                    return completed

                frames[-1][1].children.append(completed)
            else:
                raise ValueError("tree missing")

        raise ValueError("tree missing")

    def _parse_node(self):
        self._expect(";", "node missing")
        properties = {}

        while not self._at_end() and self._current() not in ";()":
            key = self._parse_property_identifier()
            values = []

            if self._at_end() or self._current() != "[":
                raise ValueError("properties without delimiter")

            while not self._at_end() and self._current() == "[":
                values.append(self._parse_value())

            if key in properties:
                raise ValueError("duplicate property")
            properties[key] = values

        return SgfTree(properties, [])

    def _parse_property_identifier(self):
        start = self.position
        while not self._at_end() and self._current() not in "[;()":
            self.position += 1

        key = self.input[start:self.position]
        if not key or any(character < "A" or character > "Z" for character in key):
            raise ValueError("property must be in uppercase")

        return key

    def _parse_value(self):
        self._expect("[", "value missing")
        value = []

        while not self._at_end():
            character = self._current()
            self.position += 1

            if character == "]":
                return "".join(value)

            if character == "\\":
                if self._at_end():
                    break

                escaped = self._current()
                self.position += 1

                # A backslash immediately before a newline joins the two
                # physical lines and contributes neither character.
                if escaped == "\n":
                    continue

                # SGF has no named whitespace escapes.  Whitespace after a
                # backslash is normalized in exactly the same way as
                # unescaped whitespace (except for the line-continuation
                # case above).
                if escaped.isspace():
                    value.append(" ")
                else:
                    value.append(escaped)
                continue

            if character.isspace() and character != "\n":
                value.append(" ")
            else:
                value.append(character)

        raise ValueError("value missing")

    def _expect(self, character, message):
        if self._at_end() or self._current() != character:
            raise ValueError(message)
        self.position += 1

    def _at_end(self):
        return self.position >= len(self.input)

    def _current(self):
        return self.input[self.position]


def parse(input_string):
    return _Parser(input_string).parse()
